"""Generate findings from the actual analytical database, never from constants."""
import json
from pathlib import Path
from . import analytics as a
from .ingest import DEFAULT_DB, ROOT, SOURCE


def main():
    if not DEFAULT_DB.exists():
        raise SystemExit('No real analytical database. Run ingestion first; no findings generated.')
    with a.connect(DEFAULT_DB) as db:
        q, k, customer = a.quality(db), a.overview(db), a.customers(db)
        monthly, countries, products = a.monthly(db), a.geography(db), a.products(db)
        units = a.products(db, metric='quantity')
        leader_audit = [dict(row) for row in db.execute('SELECT invoice, quantity, invoice_date, exclusion_reason FROM row_audit WHERE stock_code = ? ORDER BY invoice_date', (units[0]['stock_code'],))] if units else []
        if q['provenance'].get('source') == 'explicit test fixture':
            raise SystemExit('Refusing to publish a business report from a test fixture.')
        assert abs(sum(m['revenue'] for m in monthly) - k['revenue']) < .001
        assert abs(sum(c['revenue'] for c in countries) - k['revenue']) < .001
        # Independently reconstruct from retained normalized audit lines in Pandas.
        import pandas as pd
        audit = pd.read_sql_query("SELECT * FROM row_audit WHERE exclusion_reason='valid_sale'", db)
        assert abs(float((audit.quantity * audit.unit_price).sum()) - k['revenue']) < .01
        assert int(audit.invoice.nunique()) == k['orders']
        assert int(audit.customer_id.nunique()) == k['customers']
    complete = [m for m in monthly if not m['partial']]
    peak = max(complete, key=lambda m: m['revenue']) if complete else None
    top_country = countries[0] if countries else None
    lines = ['# MetricFlow analysis report', '',
        'Generated by `python -m backend.app.report` from executed SQLite queries and an independent Pandas reconciliation. Values are historical gross valid sales in GBP, not net revenue or profit.', '',
        '## Provenance', '', f"- Official dataset: UCI Online Retail (Daqing Chen, 2015), DOI 10.24432/C5BW33, CC BY 4.0.",
        f"- Imported file: `{q['provenance'].get('file')}`", f"- Download/import source: {q['provenance'].get('source')}",
        f"- SHA-256: `{q['provenance'].get('sha256')}`", f"- Observed dates: {q['min_date']} through {q['max_date']}.",
        ('- Direct UCI download was blocked by the cloud network proxy (HTTP 403). The workbook was explicitly imported from the recorded public mirror. Its schema, row count and coverage were checked; byte equality with the currently inaccessible UCI-hosted file has not been independently established.' if 'raw.githubusercontent.com' in q['provenance'].get('source','') else 'The preserved workbook and its recorded provenance identify this import; verify local-import provenance before interpreting findings.'), '',
        '## Executive KPIs', '', '| Metric | Calculated value |', '| --- | ---: |',
        f"| Gross sales revenue | £{k['revenue']:,.2f} |", f"| Completed orders (distinct sales invoices) | {k['orders']:,} |",
        f"| Average order value | £{k['average_order_value']:,.2f} |", f"| Identifiable customers | {k['customers']:,} |",
        f"| Repeat customer rate | {customer['repeat_customer_rate']:.2%} |", '',
        '## Data quality', '', f"{q['raw_rows']:,} raw rows → {q['valid_sales_rows']:,} valid sales rows; {q['excluded_rows']:,} excluded.", '',
        '| Mutually exclusive primary exclusion | Rows |', '| --- | ---: |',
        *[f'| {key} | {value:,} |' for key,value in q['excluded_by_reason'].items()], '',
        f"{q['missing_customer_ids']:,} raw rows lack a valid customer ID; {q['valid_sales_missing_customer_ids']:,} otherwise-valid sales rows are excluded only from customer measures. {q['flags']['cancellation']:,} cancellation flags and {q['negative_quantities']:,} negative quantities overlap other flags.", '',
        '## Findings and interpretation', '']
    if top_country:
        lines += [f"1. **Country concentration:** {top_country['country']} accounts for £{top_country['revenue']:,.2f} ({top_country['revenue']/k['revenue']:.2%}) of gross valid sales, across {top_country['orders']:,} invoices. This describes a geographically concentrated observed revenue mix; it does not establish market size or untapped demand."]
    if peak:
        lines += [f"2. **Seasonal pattern:** {peak['month']} is the largest complete observed calendar month at £{peak['revenue']:,.2f} and {peak['orders']:,} orders. A single annual cycle cannot establish repeatable seasonality or causation; December 2011 is incomplete and is not a comparable full month."]
    if products:
        p = products[0]
        lines += [f"3. **Product concentration:** stock code {p['stock_code']} ({p['description']}) leads revenue at £{p['revenue']:,.2f}. Stock code {units[0]['stock_code']} leads units at {units[0]['quantity']:,}. Revenue and unit rankings answer different questions; cost and margin data are absent."]
    if len(leader_audit) <= 10 and any(row['exclusion_reason'] == 'cancellation' for row in leader_audit):
        lines += ['', '**Audit evidence behind the unit leader:**', '', '| Invoice | Quantity | Source timestamp | Treatment |', '| --- | ---: | --- | --- |', *[f"| {row['invoice']} | {row['quantity']:,.0f} | {row['invoice_date']} | {row['exclusion_reason']} |" for row in leader_audit], '', 'An equal opposite-quantity cancellation appears shortly after the large positive sale. The gross-sales policy retains the positive line and excludes the cancellation; this ranking must not be interpreted as retained demand. No general return-to-sale matching is claimed.', '']
    lines += [f"4. **Observed repeat purchasing:** {customer['repeat_customers']:,} of {customer['customers']:,} identifiable customers placed at least two distinct orders ({customer['repeat_customer_rate']:.2%}). This is repeat purchasing within the observed window, not retention, churn, or lifetime behavior.", '',
        '## Monthly evidence', '', '| Month | Gross revenue | Orders | Revenue MoM |', '| --- | ---: | ---: | --- |']
    for m in monthly:
        change = f"{m['mom_change_pct']:+.2f}%" if m['mom_change_pct'] is not None else 'Not comparable / partial'
        lines.append(f"| {m['month']}{' (partial)' if m['partial'] else ''} | £{m['revenue']:,.2f} | {m['orders']:,} | {change} |")
    lines += ['', '## Limitations and next steps', '',
        '- Cancellations/returns are excluded instead of netted. Gross sales can overstate retained customer spend. Pairing returns to original invoices requires separate work.',
        '- Exact duplicates are removed after their first occurrence; legitimate repeated lines might be indistinguishable.',
        '- Positive non-merchandise stock codes (postage, fees) remain in sales and product rankings. This prevents undocumented exclusions but limits interpretation as merchandise-only sales.',
        '- Missing customer IDs bias customer measures; geographic results use invoice country, not verified residence.',
        '- No fulfillment status, costs, traffic, profit, conversion, customer acquisition cost, or causal evidence is available.',
        '- Compare the preserved workbook checksum against an official UCI download when network access permits. Investigate product description changes and return matching before extending the metrics.',
        '- Validation: SQL totals reconciled across monthly/country aggregations and independently reconstructed Pandas revenue, distinct invoices, and identifiable customers.', '']
    (ROOT / 'docs/ANALYSIS_REPORT.md').write_text('\n'.join(lines))
    (ROOT / 'data/processed/analysis-summary.json').write_text(json.dumps(dict(overview=k, quality=q, customers=customer), indent=2))
    print(json.dumps(k, indent=2))
    print('Wrote docs/ANALYSIS_REPORT.md; independent Pandas reconciliation passed.')

if __name__ == '__main__':
    main()
